mapper.select:
SELECT m.tenant_id,m.province_id, m.city_id, m.county_id,m.town_id, sum( m.yesterday_all ) AS yesterday_all,
    sum( m.today_all ) AS today_all, sum( m.false_all ) AS false_all, sum( m.today_process ) AS today_process,
    sum( m.today_complete ) AS today_complete, 0 AS pendding_receive, 0 AS pendding_judged, 0 AS pending_dispatched,
    0 AS pedding_disposal, 0 AS pending_approve, 0 AS pendding_Leader_approve, sum(m.overtime)    AS overtime,#{handleDateTime} as 'handleDateTime'
FROM (
    SELECT a.tenant_id,a.province_code AS province_id, a.city_code AS city_id,a.county_code AS county_id,a.town_code AS town_id,a.device_code,
    IF (DATE_FORMAT( a.alarm_time, '%Y-%m-%d' ) = DATE_FORMAT( DATE_SUB( #{handleDate}, INTERVAL 1 DAY ),
        '%Y-%m-%d' ), 1, 0 ) AS yesterday_all,
    IF ( DATE_FORMAT( a.alarm_time, '%Y-%m-%d' ) = #{handleDate}, 1, 0 ) AS today_all,
    IF ( DATE_FORMAT( a.alarm_time, '%Y-%m-%d' ) = #{handleDate}
            AND a.judge_result = '0', 1, 0 ) AS false_all,
    IF ( DATE_FORMAT( a.alarm_time, '%Y-%m-%d' ) = #{handleDate}
             AND ((a.order_status IN ( '1', '2', '3', '4', '5' )AND a.enable_acceptance_mode !='1')OR a.enable_acceptance_mode = '1'), 1, 0 ) AS today_process,
           IF ( DATE_FORMAT( a.alarm_time, '%Y-%m-%d' ) = #{handleDate}
        AND a.order_status IN ('6','0','7'), 1, 0 ) AS today_complete,
    IF( DATE_FORMAT( a.alarm_time, '%Y-%m-%d' ) = #{handleDate} AND TIMESTAMPDIFF(MINUTE,a.flow_node_time, NOW()) > a.time_limit
           AND a.time_limit IS NOT NULL, 1, 0) AS overtime
    FROM ${tableName} a
    WHERE a.delete_flag = '0'  and a.alarm_time >= #{startDate,jdbcType=VARCHAR} and a.alarm_time <= #{endDate,jdbcType=VARCHAR}
) m GROUP BY m.tenant_id,m.province_id, m.city_id, m.county_id,m.town_id;

