SELECT a.tenant_id, a.province_code, a.city_code, a.county_code, CONCAT( province_name, city_name, county_name ) AS 'regionName', a.town_code, a.town_name, count( DISTINCT a.warning_order_id ) AS warning_num, date_format( alarm_time, '%Y' ) AS year_str, date_format( alarm_time, '%c' ) AS month_str, date_format( alarm_time, '%e' ) AS day_str, alarm_time, COUNT( IF (judge_result = '1', 1, NULL )) AS real_num, COUNT(IF(order_status = '0', 1, NULL)) AS false_num, COUNT(IF (order_status = '7', 1, NULL )) AS repeat_complete_num FROM ${tableName} a WHERE delete_flag = '0'
AND DATE_FORMAT( alarm_time, '%Y-%m-%d' ) = #{handleDate}
GROUP BY a.tenant_id, a.province_code, a.city_code, a.county_code, a.town_code, DATE_FORMAT( alarm_time, '%Y-%m-%d' )

SELECT ord.province_code AS provinceId,ord.city_code AS cityId,ord.county_code AS countyId, COUNT(if(UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) < '3600',1,NULL)) AS lessOne, COUNT(if(UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) >= '3600' AND UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) <= '18000',1,NULL)) AS 'oneFive', COUNT(if(UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) > '18000' AND UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) <= '36000',1,NULL)) AS 'fiveTen', COUNT(if(UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) > '36000',1,NULL)) AS 'moreTen', ord.modifier_date,ord.alarm_time, year(ord.modifier_date) as year_str, MONTH(ord.modifier_date) as month_str, DAY(ord.modifier_date) as day_str FROM ${tableName} ord WHERE ord.delete_flag = '0' AND ord.order_status IN ('0','6','7')
AND DATE_FORMAT(ord.modifier_date, '%Y-%m-%d') = #{handleDate}
and DATE_FORMAT(ord.modifier_date, '%Y-%m') = #{handleDate}
GROUP BY ord.province_code,ord.city_code,ord.county_code,ord.device_code, ord.app_ver_code, ord.industry_code, ord.warning_source ,DATE_FORMAT(ord.modifier_date, '%Y-%m-%d'),DATE_FORMAT(ord.alarm_time, '%Y-%m-%d')

