AND DATE_FORMAT(modifier_date, '%Y-%m-%d') = #{handleDate}
and DATE_FORMAT(modifier_date, '%Y-%m') = #{handleDate}
) a GROUP BY a.province_code, a.city_code, a.county_code, DATE_FORMAT(modifier_date, '%Y-%m-%d'),DATE_FORMAT(alarm_time, '%Y-%m-%d')

