mapper.select:
SELECT aa.tenant_id, aa.province_code, aa.city_code, aa.county_code, aa.town_code, aa.alarm_time, aa.warning_source, aa.warning_type_id, COUNT(1) AS today_all, COUNT( IF ( aa.order_status IN ( '0', '7', '6' ), 1, NULL ) ) AS today_complete, COUNT( IF ( aa.order_status = '0', 1, NULL ) ) AS false_complete_num, COUNT( IF ( aa.order_status = '1' AND aa.enable_acceptance_mode !='1', 1, NULL ) ) AS judge_num, COUNT( IF ( aa.order_status = '2' AND aa.enable_acceptance_mode !='1', 1, NULL ) ) AS dispatch_num, COUNT( IF ( aa.order_status = '3' AND aa.enable_acceptance_mode !='1', 1, NULL ) ) AS grab_num, COUNT( IF ( aa.order_status = '4' AND aa.enable_acceptance_mode !='1', 1, NULL ) ) AS handle_num, COUNT( IF ( aa.order_status = '5' AND aa.enable_acceptance_mode !='1', 1, NULL ) ) AS approve_num, COUNT( IF ( aa.order_status = '6', 1, NULL ) ) AS order_complete_num, COUNT( IF ( aa.order_status = '7', 1, NULL ) ) AS repeat_complete_num, COUNT( IF ( aa.order_status = '0', 1, NULL ) ) AS false_num, COUNT( IF ( aa.judge_result = '1', 1, NULL ) ) AS real_num, COUNT( IF ( aa.enable_acceptance_mode = '1', 1, NULL )) AS acceptance_num, SUM( IF ( aa.order_status IN ( '0', '7', '6' ), duration, NULL )) AS duration, COUNT( IF ( aa.warning_source = '1', 1, NULL ) ) AS ai_num, COUNT( IF ( aa.warning_source = '2', 1, NULL ) ) AS manual_num, COUNT( IF ( aa.warning_source = '3', 1, NULL ) ) AS onekey_num, COUNT( IF ( aa.order_status = '1' AND aa.enable_acceptance_mode !='1' AND aa.judge_result = '1', 1, NULL ) ) AS judge_real_num, COUNT( IF ( aa.order_status = '2' AND aa.enable_acceptance_mode !='1' AND aa.judge_result = '1', 1, NULL ) ) AS dispatch_real_num, COUNT( IF ( aa.order_status = '4' AND aa.enable_acceptance_mode !='1' AND aa.judge_result = '1', 1, NULL ) ) AS handle_real_num, COUNT( IF ( aa.order_status = '5' AND aa.enable_acceptance_mode !='1' AND aa.judge_result = '1', 1, NULL ) ) AS approve_real_num, COUNT( IF ( aa.order_status = '6' AND aa.judge_result = '1', 1, NULL ) ) AS order_complete_real_num, COUNT( IF ( aa.enable_acceptance_mode = '1' AND aa.judge_result = '1', 1, NULL )) AS acceptance_real_num, YEAR ( aa.alarm_time ) AS year_str, MONTH ( aa.alarm_time ) AS month_str, DAY ( aa.alarm_time ) AS day_str FROM ( SELECT ord.tenant_id, ord.province_code, ord.city_code, ord.county_code, ord.town_code, ord.alarm_time, ord.order_status, ord.warning_source, ord.warning_type_id, ord.judge_result, ord.enable_acceptance_mode, UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) AS duration FROM ${tableName} ord WHERE ord.delete_flag = '0'
and YEAR ( ord.alarm_time ) = #{year}
and MONTH ( ord.alarm_time ) = #{month}
and DAY ( ord.alarm_time ) = #{day}
) aa
GROUP BY aa.province_code, aa.city_code, aa.county_code, aa.town_code, aa.tenant_id, aa.warning_source, aa.warning_type_id, DATE_FORMAT(aa.alarm_time, '%Y-%m-%d')

