        SELECT ord.province_code,ord.city_code,ord.county_code
        FROM ${tableName} ord WHERE ord.delete_flag = '0'
            AND DATE_FORMAT(ord.alarm_time ,'%Y') = #{handleYear}
		) aa GROUP BY aa.province_code,aa.city_code,aa.county_code;

SELECT aa.tenant_id,aa.province_code,aa.city_code,aa.county_code,aa.town_code, jt.sub_type AS warning_type_id, COUNT( IF (aa.warning_source = '1', 1, NULL)) AS ai_num, COUNT( IF (aa.warning_source = '1' AND aa.order_status IN ('0', '2', '3', '4', '5', '6', '7'), 1, NULL ) ) AS judge_num, COUNT( IF ( aa.judge_result = '1', 1, NULL )) AS real_num, COUNT(IF(aa.order_status = '0', 1, NULL)) AS false_num, COUNT(IF ( aa.order_status = '7', 1, NULL )) AS repeat_complete_num, count(*) num,YEAR(aa.alarm_time) as year_str,MONTH(aa.alarm_time) as month_str,DAY(aa.alarm_time) as day_str,aa.alarm_time FROM ${tableName} aa LEFT JOIN JSON_TABLE( IF(aa.sub_scenes IS NULL OR JSON_TYPE(aa.sub_scenes)='NULL' OR JSON_LENGTH(aa.sub_scenes)=0, JSON_ARRAY(aa.warning_type_id), aa.sub_scenes), '$[*]' COLUMNS (sub_type VARCHAR(64) PATH '$') ) jt ON TRUE WHERE aa.delete_flag = '0'
and DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate}
and DATE_FORMAT(aa.alarm_time, '%Y-%m') = #{handleDate}
GROUP BY aa.tenant_id,aa.province_code,aa.city_code,aa.county_code,aa.town_code,jt.sub_type,DATE_FORMAT(aa.alarm_time, '%Y-%m-%d')

