mapper.select:
SELECT a.province_code,a.city_code,a.county_code,a.warning_type_id,a.algorithm_code, COUNT(DISTINCT a.warning_order_id) AS warning_num,COUNT(if(a.judge_result IS NOT NULL,1,NULL)) AS judge_num, COUNT(if(a.judge_result = '1',1,NULL)) AS real_num, COUNT(if(a.judge_result = '0',1,NULL)) AS false_num, COUNT(if(a.judge_result = '2',1,NULL)) AS duplicat_num, YEAR(a.alarm_time) as year_str, MONTH(a.alarm_time) as month_str, DAY(a.alarm_time) as day_str FROM ( SELECT t.warning_order_id,t.province_code,t.city_code,t.county_code,jt.sub_type AS warning_type_id, t.algorithm_code,t.judge_result,t.alarm_time FROM ${tableName} t LEFT JOIN JSON_TABLE( IF(t.sub_scenes IS NULL OR JSON_TYPE(t.sub_scenes)='NULL' OR JSON_LENGTH(t.sub_scenes)=0, JSON_ARRAY(t.warning_type_id), t.sub_scenes), '$[*]' COLUMNS (sub_type VARCHAR(64) PATH '$') ) jt ON TRUE WHERE t.delete_flag = '0' AND t.warning_source = '1'
AND DATE_FORMAT(t.alarm_time,'%Y-%m-%d') = #{handleDate}
AND DATE_FORMAT(t.alarm_time,'%Y-%m') = #{handleDate}
UNION ALL SELECT t.warning_order_id,t.province_id AS province_code,t.city_id AS city_code,t.county_id AS county_code, jt.sub_type AS warning_type_id,t.algorithm_code,NULL AS judge_result,t.alarm_time FROM vm_alarm_operate_t t LEFT JOIN JSON_TABLE( IF(t.sub_scenes IS NULL OR JSON_TYPE(t.sub_scenes)='NULL' OR JSON_LENGTH(t.sub_scenes)=0, JSON_ARRAY(t.warning_type_id), t.sub_scenes), '$[*]' COLUMNS (sub_type VARCHAR(64) PATH '$') ) jt ON TRUE WHERE t.delete_flag = '0' AND t.warning_source = '1'
AND DATE_FORMAT(t.alarm_time,'%Y-%m-%d') = #{handleDate}
AND DATE_FORMAT(t.alarm_time,'%Y-%m') = #{handleDate}
UNION ALL SELECT t.warning_order_id,t.province_code,t.city_code,t.county_code,t.warning_type_id,t.algorithm_code, NULL AS judge_result,t.alarm_time FROM vm_warning_intercept_t t WHERE t.delete_flag = '0' AND t.warning_source = '1'
AND DATE_FORMAT(t.alarm_time,'%Y-%m-%d') = #{handleDate}
AND DATE_FORMAT(t.alarm_time,'%Y-%m') = #{handleDate}
) a GROUP BY a.province_code,a.city_code,a.county_code,a.warning_type_id,a.algorithm_code, DATE_FORMAT(a.alarm_time,'%Y-%m-%d')

