SELECT province_code as province_id, city_code as city_id, county_code as county_id, province_name, city_name, county_name, town_code, town_name, alarm_time, modifier_date, tenant_id, device_code, device_name, date_format( alarm_time, '%Y' ) AS year_str, date_format( alarm_time, '%c' ) AS month_str, date_format( alarm_time, '%e' ) AS day_str, count( DISTINCT warning_order_id ) AS today_num, COUNT( IF (order_status IN ( '0', '7', '6' ), 1, NULL ) ) AS order_complete_num, COUNT( IF (order_status = '1' AND enable_acceptance_mode !='1', 1, NULL ) ) AS judge_num, COUNT( IF (order_status = '2' AND enable_acceptance_mode !='1', 1, NULL ) ) AS dispatch_num, COUNT( IF (order_status = '4' AND enable_acceptance_mode !='1', 1, NULL ) ) AS handle_num, COUNT( IF (order_status = '5' AND enable_acceptance_mode !='1', 1, NULL ) ) AS approve_num, COUNT( IF (order_status = '7', 1, NULL ) ) AS repeat_complete_num, COUNT( IF (order_status = '0', 1, NULL ) ) AS false_num, COUNT( IF (judge_result = '1', 1, NULL ) ) AS real_num, COUNT( IF (enable_acceptance_mode = '1', 1, NULL )) AS acceptance_num, COUNT( IF (order_status = '1' AND enable_acceptance_mode !='1' AND judge_result = '1', 1, NULL ) ) AS judge_real_num, COUNT( IF (order_status = '2' AND enable_acceptance_mode !='1' AND judge_result = '1', 1, NULL ) ) AS dispatch_real_num, COUNT( IF (order_status = '4' AND enable_acceptance_mode !='1' AND judge_result = '1', 1, NULL ) ) AS handle_real_num, COUNT( IF (order_status = '5' AND enable_acceptance_mode !='1' AND judge_result = '1', 1, NULL ) ) AS approve_real_num, COUNT( IF (order_status = '6' AND judge_result = '1', 1, NULL ) ) AS order_complete_real_num, COUNT( IF (enable_acceptance_mode = '1' AND judge_result = '1', 1, NULL )) AS acceptance_real_num FROM ${tableName} WHERE delete_flag = '0' AND warning_source IN('1','3','4') AND device_code IS NOT NULL AND device_code !=''
and DATE_FORMAT(alarm_time, '%Y-%m-%d') = #{handleDate}
and DATE_FORMAT(alarm_time, '%Y-%m') = #{handleDate}
GROUP BY province_code, city_code, county_code, town_code, tenant_id, device_code, DATE_FORMAT( alarm_time, '%Y-%m-%d' )

