mapper.select:
SELECT IFNULL( bb.province_code, 'null' ) AS province_id, IFNULL( bb.city_code, 'null' ) AS city_id, IFNULL( bb.county_code, 'null' ) AS county_id, IFNULL( bb.town_code, 'null' ) AS town_id, COUNT( 1 ) AS yesterday_all, YEAR ( bb.alarm_time ) AS year_str, MONTH ( bb.alarm_time ) AS month_str, DAY ( bb.alarm_time ) AS day_str, #{handleDateTime} as 'handleDateTime', bb.alarm_time as alarm_time FROM ( SELECT ord.province_code, ord.city_code, ord.county_code, ord.town_code, DATE_SUB( ord.alarm_time, INTERVAL -1 DAY ) as alarm_time FROM ${tableName} ord WHERE ord.delete_flag = '0'
and YEAR ( ord.alarm_time ) = #{year}
and MONTH ( ord.alarm_time ) = #{month}
and DAY ( ord.alarm_time ) = #{day}-1
) bb GROUP BY bb.province_code, bb.city_code, bb.county_code, bb.town_code, DATE_FORMAT( bb.alarm_time, '%Y-%m-%d' )

